// Singleton-safe hot config:
public class Poller(IOptionsMonitor<PollOptions> monitor)
{
    public async Task RunAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(monitor.CurrentValue.Interval, ct); // live reload!
            await PollAsync(ct);
        }
    }
}
